import React, { useState } from 'react';
import { ModelSelector } from './components/ModelSelector';
import { FileUploader } from './components/FileUploader';
import { SinglePrediction } from './components/SinglePrediction';
import { DetectionSummary } from './components/DetectionSummary';
import { AttackBreakdown } from './components/AttackBreakdown';
import { BinaryMetrics } from './components/BinaryMetrics';
import { MetricsExplainer } from './components/MetricsExplainer';
import './App.css';

function App() {
  const [modelLoaded, setModelLoaded] = useState(false);
  const [predictions, setPredictions] = useState(null);

  const handleModelLoad = (data) => {
    setModelLoaded(true);
  };

  const handleFileProcess = (data) => {
    setPredictions(data);
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1>🛡️ IDS Using Ensemble — Multi-class (Type + Attack/Benign)</h1>
      </header>

      <div className="app-layout">
        <ModelSelector onModelLoad={handleModelLoad} />
        
        <main className="app-main">
          {!modelLoaded ? (
            <div className="info-box">
              Select and load a model to begin.
            </div>
          ) : (
            <>
              <FileUploader onFileProcess={handleFileProcess} />

              {predictions && (
                <>
                  {predictions.single ? (
                    <SinglePrediction 
                      prediction={predictions.pred_type}
                      probability={predictions.prob_attack}
                      topClasses={predictions.top_classes}
                    />
                  ) : (
                    <>
                      <DetectionSummary stats={predictions.stats} />
                      <AttackBreakdown attackCounts={predictions.attack_counts} />
                      
                      {predictions.metrics && (
                        <>
                          <BinaryMetrics 
                            metrics={predictions.metrics}
                            confusion={predictions.confusion}
                          />
                          <MetricsExplainer />
                        </>
                      )}
                    </>
                  )}

                  <div className="card">
                    <h3>⬇️ Download Predictions</h3>
                    <a 
                      href={predictions.download_url} 
                      download="ids_predictions.csv"
                      className="btn-download"
                    >
                      Download CSV
                    </a>
                  </div>
                </>
              )}
            </>
          )}
        </main>
      </div>
    </div>
  );
}

export default App;
